		public static List<SpellResolver.EntityData> BuildEntitiesFromState(
			CharacterState state, CharacterDefinition def, BakedAnimationData baked,
			string targetAnim, int animFrame, ulong entityId = 0)
		{
			var list = new List<SpellResolver.EntityData>();
			AppendEntitiesFromState(state, def, baked, targetAnim, animFrame, entityId, list);
			return list;
		}

		private static void AppendEntitiesFromState(CharacterState state, CharacterDefinition def,
			BakedAnimationData baked, string targetAnim, int animFrame, ulong entityId,
			List<SpellResolver.EntityData> list)
		{
			if (baked != null && def.HurtboxBoneDefs != null && def.HurtboxBoneDefs.Length > 0)
			{
				int animIdx = baked.FindAnimIndex(targetAnim);
				if (animIdx < 0) { targetAnim = "idle"; animIdx = baked.FindAnimIndex(targetAnim); }
				if (animIdx >= 0)
				{
					int fc = baked.Animations[animIdx].FrameCount;
					if (animFrame >= fc) animFrame = fc - 1;
					float px = state.PX, py = state.PY, pz = state.PZ;
					float yaw = state.FacingYaw;
					float cos = MathF.Cos(yaw), sin = MathF.Sin(yaw);
					float scale = def.HurtboxBoneScale;
					for (int bi = 0; bi < def.HurtboxBoneDefs.Length; bi++)
					{
						var hbd = def.HurtboxBoneDefs[bi];
						if (!baked.GetBonePosition(targetAnim, animFrame, bi, out float bx, out float by, out float bz)) continue;
						bx *= scale; by *= scale; bz *= scale;
						float wx = px + ((bx * cos) + (bz * sin));
						float wy = def.BoneYToWorldY(py, by);
						float wz = pz + ((-bx * sin) + (bz * cos));
						// Per-def offset (Ability Lab authored, spec #119): applied in
						// sim-meter space, rotated by facing — matches the hitbox
						// BoneOff* convention. All shipped defs use zero offsets, so
						// this is behavior-preserving for existing characters.
						wx += (hbd.OffX * cos) + (hbd.OffZ * sin);
						wy += hbd.OffY;
						wz += (-hbd.OffX * sin) + (hbd.OffZ * cos);
						HitboxGeometry.ApplyAttackPosePitch(in state, def, ref wx, ref wy, ref wz);
						list.Add(new SpellResolver.EntityData
						{
							Id = entityId, PosX = wx, PosY = wy, PosZ = wz,
							Radius = hbd.Radius, Shape = HitboxShape.Sphere,
							EndX = wx, EndY = wy, EndZ = wz,
							InvincibilityTicks = state.InvincibilityTicks,
							Active = true,
						});
					}
				}
			}
			else if (def.HurtboxCapsules != null)
			{
				float cos = MathF.Cos(state.FacingYaw);
				float sin = MathF.Sin(state.FacingYaw);
				foreach (var cap in def.HurtboxCapsules)
				{
					float sx = state.PX + (cap.Sx * cos) + (cap.Sz * sin);
					float sy = state.PY + cap.Sy;
					float sz = state.PZ + ((-cap.Sx * sin) + (cap.Sz * cos));
					float ex = state.PX + (cap.Ex * cos) + (cap.Ez * sin);
					float ey = state.PY + cap.Ey;
					float ez = state.PZ + ((-cap.Ex * sin) + (cap.Ez * cos));
					HitboxGeometry.ApplyAttackPosePitch(in state, def, ref sx, ref sy, ref sz);
					HitboxGeometry.ApplyAttackPosePitch(in state, def, ref ex, ref ey, ref ez);
					list.Add(new SpellResolver.EntityData
					{
						Id = entityId, PosX = sx, PosY = sy, PosZ = sz, Radius = cap.Radius,
						Shape = (sx != ex || sy != ey || sz != ez) ? HitboxShape.Capsule : HitboxShape.Sphere,
						EndX = ex, EndY = ey, EndZ = ez,
						InvincibilityTicks = state.InvincibilityTicks,
						Active = true,
					});
				}
			}
		}

        /// <summary>
        /// Resolve the animation name and baked frame for hitbox/hurtbox bone lookup.
        /// Returns false when there's no valid baked data for this entity or animation index is invalid.
        /// Side effects: advances _animFrames and _prevAnimIndex for the entity.
        /// </summary>
        private bool ResolveBoneAnimFrame(ulong id, CharacterState state, CharacterDefinition def,
            out BakedAnimationData baked, out string targetAnim, out int bakedFrame, bool advanceFrame = true)
        {
            baked = null!;
            targetAnim = null!;
            bakedFrame = 0;

            if (!_bakedData.TryGetValue(id, out baked!) || def.HurtboxBoneDefs == null || def.HurtboxBoneDefs.Length == 0)
                return false;
            // Low posture tracks are static frame-zero poses. They are selected only
            // when the state is grounded and the baked payload contains the exact
            // semantic binding; absent legacy content falls through to upright
            // selection without fabricating low hurtboxes.
            if (state.IsGrounded && (state.State is ActionState.Crouching or ActionState.Sliding))
            {
                string lowAnim = state.State == ActionState.Crouching ? def.CrouchAnim : def.SlideAnim;
                int lowIdx = string.IsNullOrEmpty(lowAnim) ? -1 : baked.FindAnimIndex(lowAnim);
                if (lowIdx >= 0)
                {
                    targetAnim = lowAnim;
                    bakedFrame = 0;
                    return true;
                }
            }


            if (state.State is ActionState.AirDodgeMovement or ActionState.AirDodgeRecovery)
                targetAnim = string.IsNullOrEmpty(def.AirDodgeAnim) ? def.DashAnim : def.AirDodgeAnim;
            else if ((state.State is ActionState.Attacking or ActionState.Aiming) && state.AttackSlot > 0)
            {
                bool airborne = !state.IsGrounded;
                var cooked = def.GetCookedSlotAbility(state.AttackSlot, airborne);
                if (cooked != null)
                {
                    int stageIdx = Math.Min(state.ComboStage, (byte)(cooked.Timeline.Stages.Count - 1));
                    var stage = cooked.Timeline.Stages[stageIdx];
                    targetAnim = stage.AnimationIds.Count > 0 ? stage.AnimationIds[0] : "idle";
                }
            }
            else if (state.State == ActionState.Hitstun) targetAnim = state.HitstunLevel switch
            {
                1 => def.HitMediumAnim,
                2 => def.HitHardAnim,
                _ => def.HitSmallAnim,
            };
            else if (!state.IsGrounded) targetAnim = state.VY > 0 ? def.JumpAnim : def.FallAnim;
            else if ((state.VX * state.VX) + (state.VZ * state.VZ) > 1f) targetAnim = def.RunAnim;
            else targetAnim = def.IdleAnim;

            int animIdx = baked.FindAnimIndex(targetAnim);
            if (animIdx < 0) { targetAnim = "idle"; animIdx = baked.FindAnimIndex(targetAnim); }
            if (animIdx < 0) return false;

            int fc = baked.Animations[animIdx].FrameCount;
            int prevAnim = _prevAnimIndex.TryGetValue(id, out var p) ? p : -1;
            int frame = _animFrames.TryGetValue(id, out var f) ? f : 0;
            if (prevAnim != animIdx) frame = 0;
            if (advanceFrame)
            {
                _prevAnimIndex[id] = animIdx;
                _animFrames[id] = (frame + 1) % fc;
            }

            bakedFrame = frame;

using System;

namespace SlopArena.Shared;

/// <summary>
/// Pure hitbox geometry: resolves a HitboxEvent's world-space capsule endpoints from a
/// character state + pose. Shared by the simulation (ServerAbility.SpawnHitbox), the
/// Ability Lab preview tool, and tests — one implementation so previews cannot drift
/// from what the server resolves (spec #119).
/// </summary>
public static class HitboxGeometry
{
    /// <summary>Rotate a yaw-resolved world point around the simulation hip pivot.</summary>
    /// <remarks>Positive pitch raises points in front of the fighter; facing yaw selects forward.</remarks>
    public static void ApplyAttackPosePitch(
        in CharacterState state, CharacterDefinition def,
        ref float worldX, ref float worldY, ref float worldZ)
    {
        float pitch = state.AttackPosePitch;
        if (pitch == 0f) return;

        float pivotY = def.BoneYToWorldY(state.PY, 0f);
        float dx = worldX - state.PX;
        float dy = worldY - pivotY;
        float dz = worldZ - state.PZ;
        float sinYaw = MathF.Sin(state.FacingYaw);
        float cosYaw = MathF.Cos(state.FacingYaw);
        float forward = dx * sinYaw + dz * cosYaw;
        float right = dx * cosYaw - dz * sinYaw;
        float sinPitch = MathF.Sin(pitch);
        float cosPitch = MathF.Cos(pitch);
        float pitchedForward = forward * cosPitch - dy * sinPitch;
        float pitchedY = forward * sinPitch + dy * cosPitch;
        worldX = state.PX + right * cosYaw + pitchedForward * sinYaw;
        worldY = pivotY + pitchedY;
        worldZ = state.PZ - right * sinYaw + pitchedForward * cosYaw;
    }

    /// <summary>
    /// Resolve a hitbox's world-space start/end positions.
    /// When evt.BoneName is set and baked data is available, positions at the bone's
    /// world position plus the OffX/Y/Z offset — the offset is anchor-relative (bone when
    /// BoneName is set, entity origin otherwise), matching the Ability Lab editor, which
    /// only authors Off*. Mirrors ServerAbility.SpawnHitbox.
    /// Bone names resolve against the baked skeleton's bone set — any baked bone is
    /// attachable (the bake can carry bones the hurtbox defs don't, e.g. toes).
    /// </summary>
    /// <param name="s">Character state: position, facing yaw, and AttackElapsedTicks for the baked-frame projection.</param>
    /// <param name="evt">The hitbox event to position.</param>
    /// <param name="baked">Baked skeleton data (nullable — bone path requires it).</param>
    /// <param name="def">Character definition (bone set + scale + duration lookup).</param>
    /// <param name="animationNames">Ability's AnimationNames[] (AnimIndex selects the pose animation).</param>
    /// <param name="animIndex">Current animation index into animationNames.</param>
    /// <param name="slot">0-based ability slot (for stage duration lookup).</param>
    /// <param name="airborne">True when the ability is an air slot — selects the air spec's stage duration.</param>
    public static void ResolvePositions(
        in CharacterState s, in HitboxEvent evt,
        BakedAnimationData? baked, CharacterDefinition? def,
        string[]? animationNames, byte animIndex, byte slot, bool airborne,
        out float wx, out float wy, out float wz,
        out float wex, out float wey, out float wez)
    {
        float cos = MathF.Cos(s.FacingYaw);
        float sin = MathF.Sin(s.FacingYaw);

        // Weapon-anchored hitboxes (a synthetic `_` baked point is involved — e.g.
        // _weapon_tip, which is baked at VISUAL scale from the actual sword) must not
        // be shrunk by HurtboxBoneScale: the blade capsule must span the exact visual
        // hand→tip, or it starts short of the hand and ends short of the tip. Both
        // endpoints of such a capsule resolve at scale 1.0.
        bool weaponAnchored =
            (evt.BoneName != null && evt.BoneName.StartsWith("_", StringComparison.Ordinal)) ||
            (evt.EndBoneName != null && evt.EndBoneName.StartsWith("_", StringComparison.Ordinal));
        float resolveScale = weaponAnchored ? 1f : (def?.HurtboxBoneScale ?? 1f);

        bool resolved = false;
        wx = wy = wz = 0f;

        // ── Bone-attached hitbox path (requires baked data) ──
        if (evt.BoneName != null && baked != null &&
            TryResolveBone(s, evt.BoneName, baked, def, animationNames, animIndex, slot, airborne, resolveScale,
                out float bx, out float by, out float bz))
        {
            wx = bx + ((evt.OffX * cos) + (evt.OffZ * sin));
            wy = by + evt.OffY;
            wz = bz + ((-evt.OffX * sin) + (evt.OffZ * cos));
            resolved = true;
        }

        // ── Fallback: entity-relative offset (standard path) ──
        if (!resolved)
        {
            wx = s.PX + ((evt.OffX * cos) + (evt.OffZ * sin));
            wy = s.PY + evt.OffY;
            wz = s.PZ + ((-evt.OffX * sin) + (evt.OffZ * cos));
        }

        // ── Capsule end: second baked point when EndBoneName is set, else the EndOff
        // delta (facing-rotated) from the start point, exactly as before. ──
        if (evt.EndBoneName != null && baked != null &&
            TryResolveBone(s, evt.EndBoneName, baked, def, animationNames, animIndex, slot, airborne, resolveScale,
                out float ex, out float ey, out float ez))
        {
            wex = ex + ((evt.EndOffX * cos) + (evt.EndOffZ * sin));
            wey = ey + evt.EndOffY;
            wez = ez + ((-evt.EndOffX * sin) + (evt.EndOffZ * cos));
        }
        else
        {
            wex = wx + ((evt.EndOffX * cos) + (evt.EndOffZ * sin));
            wey = wy + evt.EndOffY;
            wez = wz + ((-evt.EndOffX * sin) + (evt.EndOffZ * cos));
        }
        if (s.AttackPosePitch != 0f && def != null)
        {
            ApplyAttackPosePitch(in s, def, ref wx, ref wy, ref wz);
            ApplyAttackPosePitch(in s, def, ref wex, ref wey, ref wez);
        }
        }

    /// <summary>
    /// Resolve a baked point's world position for a bone name: scan the bake's
    /// BoneNames (HurtboxBoneDefs as a legacy fallback), project the current
    /// AttackElapsedTicks to a baked frame via the stage duration, and transform
    /// the baked Hips-relative position to world space (scale + facing yaw + Y remap).
    /// <paramref name="scale"/> is HurtboxBoneScale for ordinary bone hitboxes, but 1.0
    /// for weapon-anchored ones (synthetic `_` points are baked at visual scale).
    /// Returns false (caller falls back) when the bone, animation, or def is missing.
    /// </summary>
    private static bool TryResolveBone(
        in CharacterState s, string boneName,
        BakedAnimationData? baked, CharacterDefinition? def,
        string[]? animationNames, byte animIndex, byte slot, bool airborne, float scale,
        out float x, out float y, out float z)
    {
        x = y = z = 0f;
        if (baked == null || def == null) return false;

        // The bake holds exactly the bones the baker wrote (SlopArenaBaker's curated
        // mixamorig list: head/spine2/hips/hands/feet/toes, plus synthetic points
        // like _weapon_tip); GetBonePosition indexes BoneNames directly.
        // HurtboxBoneDefs lookup is kept as a legacy fallback for defs whose bones
        // aren't present in the bake.
        int bi = -1;
        if (baked.BoneNames != null)
        {
            for (int i = 0; i < baked.BoneNames.Length; i++)
            {
                if (string.Equals(baked.BoneNames[i], boneName, StringComparison.Ordinal)) { bi = i; break; }
            }
        }
        if (bi < 0 && def.HurtboxBoneDefs != null)
        {
            for (int i = 0; i < def.HurtboxBoneDefs.Length; i++)
            {
                if (def.HurtboxBoneDefs[i].BoneName == boneName) { bi = i; break; }
            }
        }
        if (bi < 0) return false;

        string targetAnim = animationNames != null && animationNames.Length > animIndex
            ? animationNames[animIndex] : "idle";
        int animIdx = baked.FindAnimIndex(targetAnim);
        if (animIdx < 0) { targetAnim = "idle"; animIdx = baked.FindAnimIndex(targetAnim); }
        if (animIdx < 0) return false;

        int fc = baked.Animations[animIdx].FrameCount;
        var spec = def.GetSlotAbility(slot, airborne);
        int durationTicks = (spec != null && animIndex < spec.Stages.Length)
            ? spec.Stages[animIndex].DurationTicks
            : 60;
        int bakedFrame = durationTicks > 0
            ? Math.Min(s.AttackElapsedTicks * fc / durationTicks, fc - 1)
            : Math.Min(s.AttackElapsedTicks, fc - 1);
        if (bakedFrame >= fc) bakedFrame = fc - 1;

        if (!baked.GetBonePosition(targetAnim, bakedFrame, bi, out float bx, out float by, out float bz))
            return false;

        bx *= scale; by *= scale; bz *= scale;
        float cos = MathF.Cos(s.FacingYaw);
        float sin = MathF.Sin(s.FacingYaw);
        x = s.PX + ((bx * cos) + (bz * sin));
        y = def.BoneYToWorldY(s.PY, by);
        z = s.PZ + ((-bx * sin) + (bz * cos));
        return true;
    }
}

using System;
using System.Buffers.Binary;
using System.Text;

namespace SlopArena.Shared
{
    /// <summary>
    /// Pre-baked bone positions for one animation.
    /// Loaded from a .bin file generated by the BakeSkeleton tool.
    /// No Godot dependency — usable on server and client.
    /// </summary>
    public class BakedAnimationData
    {
        public string[] BoneNames = null!;
        public BakedAnim[] Animations = null!;

        /// <summary>
        /// One baked animation.
        /// </summary>
        public class BakedAnim
        {
            public string Name = null!;
            public int FrameCount;
            /// <summary>positions[frame][boneIndex * 3 + 0/1/2] = x/y/z</summary>
            public float[][] Frames = null!; // [frameCount][boneCount * 3]
        }

        /// <summary>
        /// Load baked data from .bin format.
        /// </summary>
        public static BakedAnimationData LoadFromBin(byte[] data)
        {
            int pos = 0;

            // Magic
            uint magic = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
            if (magic != 0x4C454B53) // "SKEL"
                throw new Exception("Not a valid baked skeleton file");

            uint version = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
            if (version != 1)
                throw new Exception($"Unknown version: {version}");

            uint boneCount = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
            uint animCount = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;

            // Bone names
            var boneNames = new string[boneCount];
            for (int i = 0; i < boneCount; i++)
            {
                uint nameLen = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
                boneNames[i] = Encoding.UTF8.GetString(data, pos, (int)nameLen);
                pos += (int)nameLen;
            }

            // Animations
            var anims = new BakedAnim[animCount];
            for (int a = 0; a < animCount; a++)
            {
                uint nameLen = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
                string animName = Encoding.UTF8.GetString(data, pos, (int)nameLen);
                pos += (int)nameLen;

                uint frameCount32 = BinaryPrimitives.ReadUInt32LittleEndian(data.AsSpan(pos)); pos += 4;
                int frameCount = (int)frameCount32;

                int stride = (int)boneCount * 3;
                var frames = new float[frameCount][];
                for (int f = 0; f < frameCount; f++)
                {
                    var frame = new float[stride];
                    for (int s = 0; s < stride; s++)
                    {
                        frame[s] = BitConverter.Int32BitsToSingle(BinaryPrimitives.ReadInt32LittleEndian(data.AsSpan(pos)));
                        pos += 4;
                    }
                    frames[f] = frame;
                }

                anims[a] = new BakedAnim
                {
                    Name = animName,
                    FrameCount = frameCount,
                    Frames = frames,
                };
            }

            return new BakedAnimationData
            {
                BoneNames = boneNames,
                Animations = anims,
            };
        }

        /// <summary>
        /// Get the local-space position of a bone at a specific animation frame.
        /// Returns true if found. Positions are (x, y, z).
        /// </summary>
        public bool GetBonePosition(string animName, int frameIndex, int boneDefIndex, out float x, out float y, out float z)
        {
            x = y = z = 0;

            // Find animation
            for (int a = 0; a < Animations.Length; a++)
            {
                if (Animations[a].Name == animName)
                {
                    int fc = Animations[a].FrameCount;
                    if (frameIndex < 0) frameIndex = 0;
                    if (frameIndex >= fc) frameIndex = fc - 1;

                    int stride = BoneNames.Length * 3;
                    int baseIdx = boneDefIndex * 3;
                    if (baseIdx + 2 < stride)
                    {
                        x = Animations[a].Frames[frameIndex][baseIdx];
                        y = Animations[a].Frames[frameIndex][baseIdx + 1];
                        z = Animations[a].Frames[frameIndex][baseIdx + 2];
                        return true;
                    }
                    return false;
                }
            }
            return false;
        }

        /// <summary>
        /// Returns the minimum Y across all bones at frame 0 of the "idle" animation.
        /// Negative = feet/toes below Hips. Used to compute HipHeight for character defs.
        /// Returns 0 if idle animation is not found.
        /// </summary>
        public float GetMinBoneY()
        {
            for (int a = 0; a < Animations.Length; a++)
            {
                if (Animations[a].Name == "idle")
                {
                    int stride = BoneNames.Length * 3;
                    float minY = float.MaxValue;
                    for (int b = 0; b < BoneNames.Length; b++)
                    {
                        float y = Animations[a].Frames[0][b * 3 + 1];
                        if (y < minY) minY = y;
                    }
                    return minY;
                }
            }
            return 0f;
        }

        /// <summary>
        /// Find animation index by name, or -1.
        /// </summary>
        public int FindAnimIndex(string name)
        {
            for (int i = 0; i < Animations.Length; i++)
                if (Animations[i].Name == name)
                    return i;
            return -1;
        }

        /// <summary>
        /// Frame count for an animation, or -1 when the animation is not in the bake.
        /// </summary>
        public int FrameCountFor(string animName)
        {
            int idx = FindAnimIndex(animName);
            return idx >= 0 ? Animations[idx].FrameCount : -1;
        }
    }
}

