import json, struct, sys
MAP = {"bone.head":"mixamorig:Head","bone.hips":"mixamorig:Hips","bone.spine":"mixamorig:Spine2",
       "bone.spine2":"mixamorig:Spine2",  # proposed
       "bone.right-hand":"mixamorig:RightHand","bone.left-hand":"mixamorig:LeftHand",
       "bone.right-foot":"mixamorig:RightFoot","bone.left-foot":"mixamorig:LeftFoot"}
def bones(path):
    b = open(path,'rb').read(); _,_,bc,_ = struct.unpack_from('<IIII', b, 0); pos=16; out=[]
    for _ in range(bc):
        (n,) = struct.unpack_from('<I', b, pos); pos += 4; out.append(b[pos:pos+n].decode()); pos += n
    return out
def walk(node, found):
    if isinstance(node, dict):
        if 'hitbox' in node and isinstance(node['hitbox'], dict):
            h = node['hitbox']
            for k in ('startBoneId','endBoneId'):
                if h.get(k): found.add(h[k])
        for v in node.values(): walk(v, found)
    elif isinstance(node, list):
        for v in node: walk(v, found)
for p in sys.argv[1:]:
    baked = set(bones(f'content-cooked/{p}/poses.bin'))
    d = json.load(open(f'content-cooked/{p}/character.runtime.json'))
    used = set(); walk(d, used)
    missing = sorted(b for b in used if MAP.get(b, b) not in baked)
    print(p, 'hitbox bones:', sorted(used), '| unresolved by name:', missing or 'none')
